mapper.select:
SELECT
,CASE WHEN a.fabuzhe_table = 'laoshi' THEN laoshi.laoshi_name WHEN a.fabuzhe_table = 'qiye' THEN qiye.qiye_name WHEN a.fabuzhe_table = 'users' THEN users.username ELSE '' END as fabuzheName FROM gonggao a LEFT JOIN laoshi laoshi ON a.fabuzhe_table = 'laoshi' AND a.fabuzhe_id = laoshi.id LEFT JOIN qiye qiye ON a.fabuzhe_table = 'qiye' AND a.fabuzhe_id = qiye.id LEFT JOIN users users ON a.fabuzhe_table = 'users' AND a.fabuzhe_id = users.id
and a.id in
#{item}
and a.fabuzhe_id = #{params.fabuzheId}
and ( a.fabuzhe_id != #{params.excludeFabuzheId} or a.fabuzhe_role != #{params.excludeFabuzheRole} )
and a.fabuzhe_role = #{params.fabuzheRole}
and a.fabuzhe_table = #{params.fabuzheTable}
and a.gonggao_name like CONCAT('%',#{params.gonggaoName},'%')
and a.gonggao_types = #{params.gonggaoTypes}
and UNIX_TIMESTAMP(a.insert_time) >= UNIX_TIMESTAMP(#{params.insertTimeStart})
and UNIX_TIMESTAMP(a.insert_time) <= UNIX_TIMESTAMP(#{params.insertTimeEnd})
and a.gonggao_content like CONCAT('%',#{params.gonggaoContent},'%')
and ( laoshi.laoshi_name like CONCAT('%',#{params.fabuzheName},'%') or qiye.qiye_name like CONCAT('%',#{params.fabuzheName},'%') or users.username like CONCAT('%',#{params.fabuzheName},'%') )
order by a.${params.orderBy} desc
